import warnings
from statsmodels.tsa.holtwinters import ExponentialSmoothing
y = df['sales_units'].asfreq('MS')
models=[]
for trend in ['add','mul',None]:
    for damped in [True, False]:
        if trend is None and damped: continue
        for seasonal in ['add','mul',None]:
            if seasonal is None:
                sp=None
            else:
                sp=12
                if len(y)<24: continue
            try:
                with warnings.catch_warnings():
                    warnings.simplefilter("ignore")
                    fit=ExponentialSmoothing(y, trend=trend, damped_trend=damped, seasonal=seasonal, seasonal_periods=sp, initialization_method='estimated').fit(optimized=True)
                pred=fit.forecast(3).iloc[-1]
                models.append((trend,damped,seasonal,fit.aic,pred,fit.sse))
            except Exception as e:
                pass
sorted(models, key=lambda x:x[3])[:10]
